@CrossOrigin
@RestController
@RequestMapping("/SubscriptionQuery")
public class SubscriptionQueryRestController extends BaseSpringRestController {
	
	public SubscriptionQueryRestController( SubscriptionService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Subscription using a UUID
     * @param		UUID subscriptionId
     * @return		Subscription
     */    
    @GetMapping("/load")
    public Subscription load( @RequestParam(required=true) UUID subscriptionId ) {
    	Subscription entity = null;

    	try {  
    		entity = service.getSubscription( new SubscriptionFetchOneSummary( subscriptionId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Subscription using Id " + subscriptionId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Subscription business objects
     * @return		Set<Subscription>
     */
    @GetMapping("/")
    public List<Subscription> loadAll() {                
    	List<Subscription> subscriptionList = null;
        
    	try {
            // load the Subscription
            subscriptionList = service.getAllSubscription();
            
            if ( subscriptionList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Subscriptions" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Subscriptions ", exc );
        	return null;
        }

        return subscriptionList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Subscription subscription = null;
    protected SubscriptionService service = null;
    private static final Logger LOGGER = Logger.getLogger(SubscriptionQueryRestController.class.getName());
    
}
